validator:
function validate(input) {
  const [{ Flights = [], Passengers = [] }] = input;
  const flights = new Set(), passengers = new Set();
  for (const [id, capacity] of Flights) {
    if (id === null) return 'Every flight needs a flight_id.';
    if (flights.has(id)) return `flight_id ${id} appears twice in Flights.`;
    flights.add(id);
    if (capacity === null || capacity < 1) return `Flight ${id} needs a capacity of at least 1.`;
  }
  for (const [id, flight] of Passengers) {
    if (id === null) return 'Every passenger needs a passenger_id.';
    if (passengers.has(id)) return `passenger_id ${id} appears twice in Passengers.`;
    passengers.add(id);
    if (!flights.has(flight)) return `Passenger ${id} wants flight ${flight}, which is not in Flights.`;
  }
  return null;
}

generator:
function generate(rand, size) {
  const pick = n => Math.floor(rand() * n);
  const small = size === 'small';
  const ids = small ? [1, 2, 3, 4, 5, 6, 7, 8] : Array.from({ length: 500 }, (_, i) => i + 1);
  for (let i = ids.length - 1; i > 0; i--) { const j = pick(i + 1); [ids[i], ids[j]] = [ids[j], ids[i]]; }
  const flightCount = small ? pick(6) : 500;
  const Flights = ids.slice(0, flightCount).map(id => [id, 1 + pick(small ? 3 : 6)]);
  const Passengers = [];
  const passengerCount = Flights.length ? (small ? pick(9) : 2000) : 0;
  for (let k = 0; k < passengerCount; k++) Passengers.push([101 + k, Flights[pick(Flights.length)][0]]);
  return [{ Flights, Passengers }];
}
